const assert = require('node:assert/strict');

        const { Ledger } = require('../.build/ledger');
        const { PaymentService } = require('../.build/service');
        const { Transient } = require('../.build/transport');

        const tick = () => new Promise(resolve => setTimeout(resolve, 5));
        const isKeyConflict = error => error instanceof Error && error.constructor === Error && error.message === 'key conflict';

        async function checkRetriesForwardSameReceipt() {
          const ledger = new Ledger(); const seen = []; let calls = 0;
          const service = new PaymentService(ledger, { acknowledge: async r => { seen.push(r); if (++calls < 3) throw new Transient('ack lost'); } });
          const receipt = await service.pay('shop', 'retry', 500, 3);
          assert.deepEqual(receipt, { id: 1, tenant: 'shop', key: 'retry', cents: 500 });
          assert.equal(seen.length, 3);
          for (const forwarded of seen) assert.equal(forwarded, receipt);
          assert.equal(ledger.entries.length, 1);
        }

        async function checkExhaustionRethrowsLastTransient() {
          const ledger = new Ledger(); const thrown = [];
          const service = new PaymentService(ledger, { acknowledge: async () => { const e = new Transient(`try ${thrown.length + 1}`); thrown.push(e); throw e; } });
          await assert.rejects(service.pay('shop', 'exhaust', 7, 2), error => error === thrown[1]);
          assert.equal(thrown.length, 2);
          await assert.rejects(service.pay('shop', 'once', 7, 1), error => error instanceof Transient);
          assert.equal(thrown.length, 3);
          assert.equal(ledger.entries.length, 2);
        }

        async function checkOtherErrorsAreNotRetried() {
          const boom = new TypeError('transport broke'); let calls = 0;
          const service = new PaymentService(new Ledger(), { acknowledge: async () => { calls++; throw boom; } });
          await assert.rejects(service.pay('shop', 'hard', 7, 5), error => error === boom);
          assert.equal(calls, 1);
        }

        async function checkConcurrentCallsDebitOnce() {
          const ledger = new Ledger(); let calls = 0;
          const service = new PaymentService(ledger, { acknowledge: async () => { await tick(); if (++calls === 1) throw new Transient('ack lost'); } });
          const [first, second] = await Promise.all([service.pay('shop', 'race', 42), service.pay('shop', 'race', 42)]);
          assert.deepEqual(first, { id: 1, tenant: 'shop', key: 'race', cents: 42 });
          assert.equal(first, second);
          assert.equal(ledger.entries.length, 1);

          const direct = new Ledger();
          const [a, b, c] = await Promise.all([direct.apply('shop', 'd', 9), direct.apply('shop', 'd', 9), direct.apply('shop', 'd', 9)]);
          assert.equal(a, b); assert.equal(b, c);
          assert.equal(direct.entries.length, 1);
        }

        async function checkKeyConflictDoesNotDebit() {
          const ledger = new Ledger();
          const service = new PaymentService(ledger, { acknowledge: async () => {} });
          const original = await service.pay('shop', 'conflict', 10);
          await assert.rejects(service.pay('shop', 'conflict', 11), isKeyConflict);
          await assert.rejects(ledger.apply('shop', 'conflict', 11), isKeyConflict);
          assert.equal(ledger.entries.length, 1);
          assert.equal(await service.pay('shop', 'conflict', 10), original);

          const racingLedger = new Ledger();
          const racing = new PaymentService(racingLedger, { acknowledge: async () => {} });
          const settled = await Promise.allSettled([racing.pay('shop', 'c', 5), racing.pay('shop', 'c', 6)]);
          assert.equal(settled.filter(s => s.status === 'fulfilled').length, 1);
          const rejected = settled.filter(s => s.status === 'rejected');
          assert.equal(rejected.length, 1);
          assert.ok(isKeyConflict(rejected[0].reason));
          assert.equal(racingLedger.entries.length, 1);
        }

        async function checkKeysAreScopedByTenant() {
          const ledger = new Ledger();
          const service = new PaymentService(ledger, { acknowledge: async () => {} });
          assert.deepEqual(await service.pay('alpha', 'same', 5), { id: 1, tenant: 'alpha', key: 'same', cents: 5 });
          assert.deepEqual(await service.pay('beta', 'same', 9), { id: 2, tenant: 'beta', key: 'same', cents: 9 });
          await service.pay('a|b', 'c', 1); await service.pay('a', 'b|c', 2);
          assert.equal(ledger.entries.length, 4);
        }

        async function checkInvalidInputTouchesNothing() {
          const ledger = new Ledger(); let acks = 0;
          const service = new PaymentService(ledger, { acknowledge: async () => { acks++; } });
          const invalid = [
            ['', 'k', 1], [undefined, 'k', 1], [7, 'k', 1], ['t', '', 1], ['t', undefined, 1], ['t', 7, 1],
            ['t', 'k', 0], ['t', 'k', -5], ['t', 'k', 1.5], ['t', 'k', NaN], ['t', 'k', Infinity], ['t', 'k', '5'], ['t', 'k', 2 ** 53],
            ['t', 'k', 5, 0], ['t', 'k', 5, 6], ['t', 'k', 5, 2.5], ['t', 'k', 5, NaN], ['t', 'k', 5, '3'],
          ];
          for (const args of invalid) await assert.rejects(service.pay(...args), /invalid payment/, JSON.stringify(args));
          assert.equal(ledger.entries.length, 0);
          assert.equal(acks, 0);
          await service.pay('t', 'min', 1, 1);
          await service.pay('t', 'max', 1, 5);
          assert.equal(ledger.entries.length, 2);
        }

        async function main() {
          const ledger = new Ledger(); const receipts = [];
          const service = new PaymentService(ledger, { acknowledge: async r => { receipts.push(r); } });
          assert.deepEqual(await service.pay('shop', 'sale', 123), { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
          assert.equal(ledger.entries.length, 1); assert.equal(receipts.length, 1);
          await assert.rejects(service.pay('shop', 'bad', 0), /invalid payment/);

          await checkRetriesForwardSameReceipt();
          await checkExhaustionRethrowsLastTransient();
          await checkOtherErrorsAreNotRetried();
          await checkConcurrentCallsDebitOnce();
          await checkKeyConflictDoesNotDebit();
          await checkKeysAreScopedByTenant();
          await checkInvalidInputTouchesNothing();
        }
        module.exports = main();

