export interface Receipt { id: number; tenant: string; key: string; cents: number }

export class Ledger {
  // One entry per debit that actually committed, in commit order.
  readonly entries: Receipt[] = [];
  // tenant -> idempotency key -> receipt of the debit that first used that key.
  // A nested Map keeps tenant and key separate, so no delimiter can collide.
  readonly #receiptsByKey = new Map<string, Map<string, Receipt>>();

  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // Lookup and commit happen with no await in between, so concurrent callers
    // either find the existing receipt or are the single caller that debits.
    let keys = this.#receiptsByKey.get(tenant);
    const original = keys?.get(key);
    if (original !== undefined) {
      if (original.cents !== cents) throw new Error('key conflict');
      return original;
    }
    const receipt: Receipt = { id: this.entries.length + 1, tenant, key, cents };
    if (keys === undefined) {
      keys = new Map<string, Receipt>();
      this.#receiptsByKey.set(tenant, keys);
    }
    keys.set(key, receipt);
    this.entries.push(receipt);
    return receipt;
  }
}

