import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';

const MAX_ATTEMPTS = 5;

function isNonEmptyString(value: unknown): boolean {
  return typeof value === 'string' && value.length > 0;
}

export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}

  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    // Validate everything before any ledger or transport action.
    if (
      !isNonEmptyString(tenant) ||
      !isNonEmptyString(key) ||
      !Number.isSafeInteger(cents) || cents <= 0 ||
      !Number.isInteger(attempts) || attempts < 1 || attempts > MAX_ATTEMPTS
    ) throw new Error('invalid payment');

    // Once a receipt is held, later tries re-acknowledge that same receipt and never call the ledger again.
    let receipt: Receipt | undefined;
    for (let tryNumber = 1; ; tryNumber++) {
      try {
        if (receipt === undefined) receipt = await this.ledger.apply(tenant, key, cents);
        await this.transport.acknowledge(receipt);
        return receipt;
      } catch (error) {
        // Only Transient is retried. When tries run out, the last error is rethrown as-is.
        if (!(error instanceof Transient) || tryNumber >= attempts) throw error;
      }
    }
  }
}
